const form=document.querySelector('#booking-form');
const message=document.querySelector('#form-message');
const slots=document.querySelector('#slots');
const config=window.EASY_CONFIG||{};
const savedOrders=window.EASY_SAVED_ORDERS;
const myOrdersLink=document.querySelector('.my-orders-link');
if(savedOrders?.read().length)myOrdersLink.hidden=false;
const configured=Boolean(config.supabaseUrl&&config.supabaseAnonKey);
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ulaanbaatar',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const service=form.elements.service;
const size=form.elements.vehicle_size;
const sizeInfo={small:{label:'Жижиг',type:'sedan',price:'70,000₮'},medium:{label:'Дунд',type:'sedan',price:'85,000₮'},large:{label:'Том',type:'suv',price:'105,000₮'},tall:{label:'Урт/өндөр',type:'van',price:'120,000₮'},motorcycle:{label:'Мотоцикл',type:'sedan',price:'30–60 мянга ₮'},heavy:{label:'Тусгай техник',type:'van',price:'100,000₮ / цаг'}};
function updatePrice(){const info=sizeInfo[size.value];document.querySelector('#estimated-price').textContent=service.value==='full'?info.price:'Тохирно';document.querySelector('#price-note').textContent=service.value==='full'?'Бүтэн угаалгын үнэ':'Энэ үйлчилгээний үнийг тусад нь тохирно'}
size.onchange=updatePrice;
updatePrice();
let db,coords=null,selected=null;
form.elements.booking_date.min=today();
form.elements.booking_date.value=today();
form.elements.booking_date.max=new Date(Date.now()+60*86400000).toISOString().slice(0,10);
function setMessage(text,error=false){message.textContent=text;message.classList.toggle('error',error)}
function renderSlots(hours=[]){slots.replaceChildren();for(let h=9;h<=18;h++){const found=hours.find(x=>Number(x.hour)===h);const b=document.createElement('button');b.type='button';b.textContent=`${String(h).padStart(2,'0')}:00`;b.disabled=!found?.available;b.classList.toggle('selected',selected===h&&!!found?.available);b.onclick=()=>{selected=h;form.elements.booking_hour.value=h;renderSlots(hours)};slots.append(b)}if(!hours.find(x=>Number(x.hour)===selected&&x.available)){selected=null;form.elements.booking_hour.value=''}}
async function refreshSlots(){renderSlots();if(!db)return;const {data,error}=await db.rpc('available_hours',{p_date:form.elements.booking_date.value,p_service:service.value});if(error){setMessage('Цагийн мэдээлэл ачаалсангүй. Түр хүлээгээд дахин оролдоно уу.',true);return}renderSlots(data||[])}
service.onchange=()=>{refreshSlots();updatePrice()};form.elements.booking_date.onchange=refreshSlots;
document.querySelectorAll('[data-service]').forEach(button=>button.onclick=()=>{service.value=button.dataset.service;refreshSlots();updatePrice();form.scrollIntoView({behavior:'smooth',block:'start'})});
document.querySelector('#locate').onclick=()=>{const result=document.querySelector('#location-result');if(!navigator.geolocation){result.textContent='Хаягаа гараар бичнэ үү.';return}result.textContent='Байршил авч байна…';navigator.geolocation.getCurrentPosition(({coords:c})=>{coords={latitude:c.latitude,longitude:c.longitude};const url=`https://www.google.com/maps?q=${c.latitude},${c.longitude}`;result.textContent='Байршил сонгогдлоо';const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener';link.textContent='Google Maps дээр харах ↗';document.querySelector('#map-preview').replaceChildren(link)},()=>result.textContent='Байршил олдсонгүй. Хаягаа гараар бичнэ үү.',{timeout:12000,enableHighAccuracy:true})};
if(configured){const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2');db=createClient(config.supabaseUrl,config.supabaseAnonKey);refreshSlots()}else{setMessage('Онлайн захиалга одоогоор нээгдээгүй байна. Админ өгөгдлийн сангийн холболтыг тохируулсны дараа цаг сонгох боломжтой болно.',true);form.querySelector('.submit').disabled=true;renderSlots()}
form.onsubmit=async e=>{e.preventDefault();if(!db)return;if(form.elements.company.value)return;if(selected===null){setMessage('Боломжтой цаг сонгоно уу.',true);return}const button=form.querySelector('.submit');button.disabled=true;setMessage('Захиалгыг илгээж байна…');const values=Object.fromEntries(new FormData(form));const {data,error}=await db.rpc('book_visit',{p_name:values.name,p_phone:values.phone,p_vehicle_type:sizeInfo[values.vehicle_size].type,p_vehicle_model:`[${sizeInfo[values.vehicle_size].label}] ${values.vehicle_model}`,p_plate:values.plate,p_service:values.service,p_address:values.address,p_latitude:coords?.latitude??null,p_longitude:coords?.longitude??null,p_date:values.booking_date,p_hour:selected});button.disabled=false;if(error){setMessage(error.message.includes('SLOT_FULL')?'Энэ цаг дүүрсэн байна. Өөр цаг сонгоно уу.':'Захиалга илгээгдсэнгүй. Мэдээллээ шалгаад дахин оролдоно уу.',true);refreshSlots();return}const row=data?.[0];if(!row){setMessage('Захиалгын баталгааг авч чадсангүй. Админтай холбогдоно уу.',true);return}const url=new URL('order.html',location.href);url.searchParams.set('token',row.access_token);const stored=savedOrders?.save({token:row.access_token,date:values.booking_date,hour:selected,vehicle:`${sizeInfo[values.vehicle_size].label} · ${values.vehicle_model}`});if(stored)myOrdersLink.hidden=false;form.reset();coords=null;selected=null;form.elements.booking_date.value=today();refreshSlots();updatePrice();message.replaceChildren();const strong=document.createElement('strong');strong.textContent=stored?'Захиалга бүртгэгдэж, энэ төхөөрөмжид хадгалагдлаа. ':'Захиалга бүртгэгдлээ. Холбоосоо хуулж хадгалаарай. ';const link=document.createElement('a');link.href=url.href;link.textContent='Захиалгаа харах ↗';const copy=document.createElement('button');copy.type='button';copy.className='copy-order-link';copy.textContent='Холбоос хуулах';copy.onclick=async()=>{try{await navigator.clipboard.writeText(url.href);copy.textContent='Хуулагдлаа ✓'}catch{copy.textContent='Хуулах боломжгүй. Холбоосыг нээгээд хаягийг хадгална уу.'}};message.append(strong,link,copy);message.classList.remove('error');};
